/**
 * Dashboard Internationalization Module
 *
 * Single source of truth for all translatable UI strings.
 * Namespaced flat keys: "nav.messages", "common.save", "settings.language_label"
 * Supported languages: English (en), Spanish (es)
 *
 * Usage:
 *   import { t, tJs, SUPPORTED_LANGS } from "./i18n.js";
 *   t("nav.messages", "es")       // → "Mensajes"  (for HTML contexts)
 *   tJs("notif.no_notifications", "es")  // → JS-safe escaped string (for JS string contexts)
 */

