  // Gateway sub-labels
  "botbuilder.gwLabelBotTokenDiscord": { en: "Bot token", es: "Token del bot" },
  "botbuilder.gwLabelChannelIds": { en: "Channel IDs (one per line, optional — blank = any channel)", es: "IDs de canal (uno por línea, opcional — vacío = cualquier canal)" },
  "botbuilder.gwLabelAllowlistDiscord": { en: "Who may talk to it — Discord user IDs (one per line)", es: "Quién puede hablarle — IDs de usuario de Discord (uno por línea)" },
