  "botbuilder.gwLabelAppToken": { en: "App-level token (xapp-…, connections:write)", es: "Token de nivel de app (xapp-…, connections:write)" },
  "botbuilder.gwLabelAllowlistSlack": { en: "Who may talk to it — Slack user IDs (one per line, blank = anyone)", es: "Quién puede hablarle — IDs de usuario de Slack (uno por línea, vacío = cualquiera)" },
  "botbuilder.gwLabelChannelIdsSlack": { en: "Restrict to channel IDs (one per line, optional)", es: "Restringir a IDs de canal (uno por línea, opcional)" },
  "botbuilder.gwLabelPairedKiosk": { en: "Paired kiosk device", es: "Dispositivo kiosk vinculado" },
  "botbuilder.gwLabelAvatarModel": { en: "Avatar (Live2D model name, blank = bot/default)", es: "Avatar (nombre del modelo Live2D, vacío = bot/predeterminado)" },
  "botbuilder.gwHintDiscord": { en: "Discord runs via the long-lived <code>pibot-discord.service</code> (discord_gateway.mjs holds a WebSocket per bot). The <code>MessageContent</code> privileged intent must be enabled in the Discord Developer Portal. After changing token/guild/channel config, restart the service: <code>sudo systemctl restart pibot-discord</code>.", es: "Discord se ejecuta a través del servicio de larga duración <code>pibot-discord.service</code> (discord_gateway.mjs mantiene un WebSocket por bot). El intent privilegiado <code>MessageContent</code> debe estar habilitado en el Portal de Desarrolladores de Discord. Tras cambiar token/guild/canal, reinicia el servicio: <code>sudo systemctl restart pibot-discord</code>." },
  "botbuilder.gwHintTelegram": { en: "Telegram runs via the long-lived <code>pibot-gateways@&lt;instance&gt;.service</code> (gateways/telegram.mjs, long-poll — dials out, no inbound port). After changing config, restart: <code>sudo systemctl restart pibot-gateways@&lt;instance&gt;</code>.", es: "Telegram se ejecuta a través del servicio de larga duración <code>pibot-gateways@&lt;instancia&gt;.service</code> (gateways/telegram.mjs, long-poll — saliente, sin puerto entrante). Tras cambiar la configuración, reinicia: <code>sudo systemctl restart pibot-gateways@&lt;instancia&gt;</code>." },
  "botbuilder.gwHintSlack": { en: "Slack runs via the long-lived <code>pibot-gateways@&lt;instance&gt;.service</code> (gateways/slack.mjs, Socket Mode — dials out, no inbound port). Needs Socket Mode enabled + an app-level token with <code>connections:write</code>. After changing config, restart: <code>sudo systemctl restart pibot-gateways@&lt;instance&gt;</code>.", es: "Slack se ejecuta a través del servicio de larga duración <code>pibot-gateways@&lt;instancia&gt;.service</code> (gateways/slack.mjs, Socket Mode — saliente, sin puerto entrante). Necesita Socket Mode habilitado + un token de nivel de app con <code>connections:write</code>. Tras cambiar la configuración, reinicia: <code>sudo systemctl restart pibot-gateways@&lt;instancia&gt;</code>." },
  "botbuilder.bxGlassesRetiredShort": { en: "Glasses now answer as Crow", es: "Las gafas ahora responden como Crow" },
  "botbuilder.bxGlassesRetired": { en: "Glasses now answer as Crow. This bot keeps its saved glasses settings, but they no longer do anything.", es: "Las gafas ahora responden como Crow. Este bot conserva sus ajustes de gafas guardados, pero ya no hacen nada." },
  "botbuilder.gwHintCompanion": { en: "Saving binds the device (<code>bound_bot_id</code>, <code>device_kind:companion</code>) so this kiosk shows THIS bot's persona/avatar and the feature toggles above. The fast&rarr;escalate model pair is global to the companion container, routed by the gateway's <code>/llm/v1</code> router. Device toggles (social chat, face tracking) apply on the kiosk's next page load. <code>memory_integration</code> and the avatar model are config-gen settings — they only take effect after the companion config is regenerated and the container restarts. See <code>docs/guide/kiosk-mode.md</code>.", es: "Guardar enlaza el dispositivo (<code>bound_bot_id</code>, <code>device_kind:companion</code>) para que este kiosk muestre la persona/avatar y los toggles de ESTE bot. El par de modelos fast&rarr;escalate es global al contenedor companion, enrutado por el router <code>/llm/v1</code> del gateway. Los toggles de dispositivo (chat social, seguimiento facial) se aplican en la próxima carga de página del kiosk. <code>memory_integration</code> y el modelo de avatar son ajustes de generación de config — solo tienen efecto después de regenerar la config del companion y reiniciar el contenedor. Ver <code>docs/guide/kiosk-mode.md</code>." },
  "botbuilder.gwHintHousehold": { en: "Household profiles (multiple named users, each with their own avatar & voice) are configured in Settings → Companion → Household — they apply to the whole companion, not per bot.", es: "Los perfiles del hogar (varios usuarios con su propio avatar y voz) se configuran en Ajustes → Companion → Hogar; aplican a todo el companion, no por bot." },
  "botbuilder.gwHintNone": { en: "No gateway — this bot is driven only by direct injection / cards, not inbound messages.", es: "Sin gateway — este bot solo es impulsado por inyección directa / tarjetas, no por mensajes entrantes." },
