  "botbuilder.classifierNotResponding": { en: "The safety check model ({model}, {provider}) is not responding. Safety check runs on {where}. Until it is running, Auto asks about every command in Perch. Start it on the Models page.", es: "El modelo de verificación de seguridad ({model}, {provider}) no responde. La verificación se ejecuta en {where}. Mientras no esté en marcha, Automático pregunta por cada comando en Perch. Inícielo en la página Modelos." },
